    @Test fun gcmVectors() {
        for ((key, nonce, plaintext, aad, sealed) in gcm) {
            val aead = AesGcm(key)
            assertContentEquals(sealed, aead.encrypt(nonce, aad, plaintext))
            assertContentEquals(plaintext, aead.decrypt(nonce, aad, sealed))
            val forged = sealed.copyOf().also { it[it.size - 1] = (it[it.size - 1].toInt() xor 1).toByte() }
            assertNull(aead.decrypt(nonce, aad, forged))
            if (plaintext.isNotEmpty()) assertNull(aead.decrypt(nonce, aad, sealed.copyOf().also { it[0] = (it[0].toInt() xor 0x80).toByte() }))
            assertNull(aead.decrypt(nonce, aad + 0, sealed))
        }
    }
